import sys

def main():
    MOD = 998244353
    p, s, r = map(int, sys.stdin.readline().split())
    NMAX = s + p + 10
    fact = [1] * (NMAX + 1)
    for i in range(1, NMAX + 1):
        fact[i] = fact[i-1] * i % MOD
    inv_fact = [1] * (NMAX + 1)
    inv_fact[NMAX] = pow(fact[NMAX], MOD - 2, MOD)
    for i in range(NMAX, 0, -1):
        inv_fact[i-1] = inv_fact[i] * i % MOD

    def C(a, b):
        if b < 0 or a < 0 or b > a:
            return 0
        return fact[a] * inv_fact[b] % MOD * inv_fact[a-b] % MOD

    inv = [0] * (p + 2)
    for i in range(1, p + 2):
        inv[i] = pow(i, MOD - 2, MOD)

    ans = 0
    for m in range(r, s + 1):
        for k in range(0, p):
            rem = s - m * (k + 1)
            if rem < 0:
                break
            n = p - 1 - k
            if n < 0:
                break
            if n == 0:
                cnt = 1 if rem == 0 else 0
            else:
                if m == 0:
                    cnt = 0
                else:
                    cnt = 0
                    j = 0
                    while j <= n and rem - j * m >= 0:
                        term = C(n, j) * C(rem - j * m + n - 1, n - 1) % MOD
                        if j % 2 == 0:
                            cnt += term
                        else:
                            cnt -= term
                        j += 1
                    cnt %= MOD
            if cnt:
                ans = (ans + C(p - 1, k) * inv[k + 1] % MOD * cnt) % MOD

    total = C(s - r + p - 1, p - 1)
    print(ans * pow(total, MOD - 2, MOD) % MOD)

main()
